import re, pathlib, unicodedata
def anchors(text):
    out=set(); used=set(); fence=None; prev=''
    for line in text.splitlines():
        m=re.match(r'^\s{0,3}(`{3,}|~{3,})', line)
        if m:
            tok=m.group(1)
            if fence is None: fence=tok
            elif tok[0]==fence[0] and len(tok)>=len(fence) and not line.strip()[len(tok):].strip(): fence=None
            prev=''; continue
        if fence: continue
        h=re.match(r'^\s{0,3}#{1,6}\s+(.+?)(?:\s+#+)?\s*$', line)
        title=h.group(1) if h else None
        if title is None and prev.strip() and re.fullmatch(r'\s{0,3}(?:=+|-+)\s*', line): title=prev.strip()
        if title is not None:
            title=re.sub(r'<[^>]+>','',title).lower()
            base=''.join(c for c in title if c in '-_ ' or unicodedata.category(c)[0] in 'LN').replace(' ','-')
            slug=base; n=0
            while slug in used: n+=1; slug=f'{base}-{n}'
            used.add(slug); out.add(slug)
        prev=line
    return out
files=[pathlib.Path(p) for p in ['spec/PRIMITIVES.md','spec/LAYOUT.md','spec/EVENTS.md','spec/DSL.md','spec/MODIFIERS.md','spec/OPCODE.md','docs/decisions/0014-virtualized-lazy-stacks.md','docs/decisions/README.md']]
cache={p:p.read_text() for p in files}
for p in files:
    text=cache[p]
    for m in re.finditer(r'\]\(([^)]+)\)', text):
        target=m.group(1)
        if target.startswith(('http','mailto:','#')): continue
        path,_,anchor=target.partition('#')
        dest=(p.parent/path).resolve()
        if not dest.exists():
            print('MISSING FILE',p,target); continue
        if anchor:
            if dest not in cache: cache[dest]=dest.read_text()
            if anchor not in anchors(cache[dest]): print('MISSING ANCHOR',p,target)
print('done')
