                 String sliderClass = Format.classAttr("pathland-slider");
                 String label = node.strings.get(Properties.LABEL);
                 String inputAria = label != null && !label.isEmpty()
                         ? " aria-label=\"" + Format.escapeHtmlAttr(label) + "\""
                         : "";
