+                event.visibleFirstIndex(),
+                event.visibleCount(),
+            )
             event.isNavigate -> {
                 if (event.url() != null) {
                     activePath.set(event.url()!!)
                 } else {
                     navigateHandler?.accept(event)
                 }
             }
         }
     }
 }

