         0 => (34.0, 700.0),  // LargeTitle
         1 => (28.0, 700.0),  // Title
         2 => (22.0, 700.0),  // Title2
         3 => (20.0, 600.0),  // Title3
         4 => (17.0, 600.0),  // Headline
         5 => (15.0, 400.0),  // Subheadline
         6 => (15.0, 400.0),  // Body
