fn lazy_windowed(node: &Node) -> bool {
    node.u32_property(property_id::ITEM_COUNT, 0) > 0
        && node.f32_property(property_id::ITEM_EXTENT, 0.0) > 0.0
}

fn base_padding(node: &Node, side: u16) -> f32 {
    node.f32_property(
        side,
        node.f32_property(property_id::PADDING, node.content_margins().unwrap_or(0.0)),
    )
}

fn wrap_lazy_stack(...) -> String {
    let tag = ...;
    let alignment = ...;
    let align = ...;
    let count = node.u32_property(ITEM_COUNT, 0);
    let extent = node.f32_property(ITEM_EXTENT, 0.0);
    let first = node.u32_property(FIRST_ITEM_INDEX, 0);
    let spacing = node.f32_property(SPACING, 0.0).max(0.0);
    let stride = extent + spacing;
    let child_count = node.children.iter().filter(|&&c| ...).count() as u32;
    let leading = first as f32 * stride;
    let trailing = count.saturating_sub(first + child_count) as f32 * stride;
    let (top, bottom) = if vertical { (leading, trailing) } else { (0.0, 0.0) };
    let (left, right) = if vertical { (0.0, 0.0) } else { (leading, trailing) };
    let pad_top = base_padding(node, PADDING_TOP) + top;
    let pad_bottom = base_padding(node, PADDING_BOTTOM) + bottom;
    let pad_left = base_padding(node, PADDING_LEFT) + left;
    let pad_right = base_padding(node, PADDING_RIGHT) + right;
    let padding = format!(
        "padding-top:{};padding-bottom:{};padding-left:{};padding-right:{};",
        px(pad_top), px(pad_bottom), px(pad_left), px(pad_right)
    );
    let combined = format!("display:flex;flex-direction:{direction};align-items:{align};{padding}{css}");
    let stack_style = style_attr(&combined);
    let axis = if vertical { "vertical" } else { "horizontal" };
    format!(
        "<{tag} data-pathland-id=\"{id}\"{}{event}{aria}{stack_style} data-pathland-lazy=\"{axis}\" data-pathland-item-count=\"{count}\" data-pathland-item-extent=\"{}\" data-pathland-first-item-index=\"{first}\" data-pathland-item-spacing=\"{}\">{children}</{tag}>",
        slot_attrs(node),
        px(extent),
        px(spacing),
    )
}
