 /// CSS decoration (background, border, font family) for a node, keyed by its
 /// widget name (set in [`apply_style`]).
 fn style_css(node: &HostNode) -> String {
     let mut css = String::new();
     // Text color / size are emitted as CSS so they CASCADE to a control's content
     // (e.g. `.foregroundStyle`/`.fontSize` on a composite Button/container reaches
     // its child labels — SwiftUI environment semantics, spec DSL.md §5.7). On a
     // TEXT node the Pango attributes from `apply_text_style` take precedence.
     if let Some(bits) = node.properties.get(&property_id::COLOR) {
         let (r, g, b, a) = unpack_color(*bits);
         css.push_str(&format!(
             "color:rgba({:.0},{:.0},{:.0},{:.3});",
             r * 255.0,
             g * 255.0,
             b * 255.0,
             a
         ));
     }
     if let Some(bits) = node.properties.get(&property_id::TEXT_STYLE) {
         if let Some((size, weight)) = text_style_scale(f32::from_bits(*bits) as u8) {
             // Predefined typography first; explicit FONT_SIZE/FONT_WEIGHT below
             // override (raw modifiers layer on top).
             css.push_str(&format!("font-size:{size}px;font-weight:{weight};"));
         }
     }
     if let Some(bits) = node.properties.get(&property_id::FONT_SIZE) {
         let v = f32::from_bits(*bits);
         if v > 0.0 {
             css.push_str(&format!("font-size:{v}px;"));
         }
     }
     if let Some(bits) = node.properties.get(&property_id::BACKGROUND_COLOR) {
         let (r, g, b, a) = unpack_color(*bits);
         css.push_str(&format!(
             "background-color:rgba({:.0},{:.0},{:.0},{:.3});",
             r * 255.0,
             g * 255.0,
             b * 255.0,
             a
         ));
     }
     if let Some(bits) = node.properties.get(&property_id::BORDER_WIDTH) {
         let w = f32::from_bits(*bits);
         let (r, g, b, a) = unpack_color(node.u32_property(property_id::BORDER_COLOR, 0xFF00_0000));
         css.push_str(&format!(
             "border:{w}px solid rgba({:.0},{:.0},{:.0},{:.3});",
             r * 255.0,
             g * 255.0,
             b * 255.0,
             a
         ));
     }
     if let Some(bits) = node.properties.get(&property_id::BORDER_RADIUS) {
         let r = f32::from_bits(*bits);
         if r != 0.0 {
             css.push_str(&format!("border-radius:{r}px;"));
         }
     }
     if let Some(bits) = node.properties.get(&property_id::FONT_DESIGN) {
         if let Some(family) = font_design_family(f32::from_bits(*bits) as u8) {
             css.push_str(&format!("font-family:{family};"));
         }
     }
     if let Some(family) = node.string_property(property_id::FONT_FAMILY) {
         css.push_str(&format!("font-family:'{}';", family.replace('\'', "\\'")));
     }
     if let Some(bits) = node.properties.get(&property_id::FONT_WEIGHT) {
         let w = f32::from_bits(*bits);
         if w > 0.0 {
             css.push_str(&format!("font-weight:{w};"));
         }
     }
     css
 }

 /// Apply color/font-size/font-weight/design text style from properties via
 /// Pango attributes. A predefined `TEXT_STYLE` supplies the default size/weight;
 /// explicit `FONT_SIZE`/`FONT_WEIGHT` override it (raw modifiers layer on top).
 fn apply_text_style(label: &Label, node: &HostNode) {
     // Rich text uses Pango **markup** (not an `AttrList`): pango 0.20 has no
     // link attribute, and markup gives us `<a href>` plus nested spans for the
     // style runs. Plain text keeps the existing `AttrList` path.
     if let Some(markup) = attributed_markup(node) {
         label.set_attributes(None);
         label.set_markup(&markup);
         apply_text_layout(label, node);
         return;
     }

     let attrs = pango::AttrList::new();
     let style = node
         .properties
         .get(&property_id::TEXT_STYLE)
         .map(|b| f32::from_bits(*b) as u8);
     let style_scale = style.and_then(text_style_scale);
     let size = node
         .properties
         .get(&property_id::FONT_SIZE)
         .map(|b| f32::from_bits(*b))
         .filter(|v| *v > 0.0)
         .or_else(|| style_scale.map(|(s, _)| s));
     let weight = node
         .properties
         .get(&property_id::FONT_WEIGHT)
         .map(|b| f32::from_bits(*b))
         .filter(|v| *v > 0.0)
         .or_else(|| style_scale.map(|(_, w)| w));
     let design_family = node
         .properties
         .get(&property_id::FONT_DESIGN)
         .map(|b| f32::from_bits(*b) as u8)
         .and_then(font_design_family);
     let family = node
         .string_property(property_id::FONT_FAMILY)
         .or(design_family);
     if size.is_some() || weight.is_some() || family.is_some() {
         let mut desc = pango::FontDescription::new();
         if let Some(size) = size {
             desc.set_size((size.max(0.0) as i32) * pango::SCALE);
         }
         if let Some(weight) = weight {
             desc.set_weight(pango_weight(weight));
         }
         if let Some(family) = family {
             desc.set_family(family);
         }
         attrs.insert(pango::AttrFontDesc::new(&desc));
     }
     if let Some(color) = node.properties.get(&property_id::COLOR) {
         let c = *color;
         let red = (((c >> 16) & 0xFF) as u16) * 257;
         let green = (((c >> 8) & 0xFF) as u16) * 257;
         let blue = ((c & 0xFF) as u16) * 257;
         let mut fg = pango::AttrColor::new_foreground(red, green, blue);
         fg.set_start_index(0);
         fg.set_end_index(u32::MAX);
         attrs.insert(fg);
     }
     label.set_attributes(Some(&attrs));
     apply_text_layout(label, node);
 }

 /// Content fitting (spec LAYOUT.md): a Fixed `WIDTH` wraps the text within the
 /// box; `LINE_LIMIT` clamps the line count and truncates with an ellipsis whose
 /// position follows `TRUNCATION_MODE` (Tail default). A `TRUNCATION_MODE` alone
 /// has no observable effect (SwiftUI-aligned).
 fn apply_text_layout(label: &Label, node: &HostNode) {
     let fixed_width = fixed_size(node, property_id::WIDTH).is_some();
     let line_limit = node.properties.get(&property_id::LINE_LIMIT).copied();
     let trunc = node
         .properties
         .get(&property_id::TRUNCATION_MODE)
         .map(|b| f32::from_bits(*b) as u8);
     if fixed_width || line_limit.is_some_and(|n| n > 0) {
         label.set_wrap(true);
         label.set_wrap_mode(pango::WrapMode::WordChar);
     }
     if let Some(n) = line_limit {
         if n > 0 {
             label.set_lines(n as i32);
             label.set_ellipsize(
                 trunc
                     .map(layout::ellipsize_from)
                     .unwrap_or(pango::EllipsizeMode::End),
             );
         }
     }
 }

 /// Build Pango markup for an attributed-text node: base node styles as an outer
 /// span, then one span per non-overlapping segment, with `<a href>` for links.
 /// Returns `None` for plain text (the `AttrList` path owns it).
 fn attributed_markup(node: &HostNode) -> Option<String> {
     let attributed = node.attributed.as_ref()?;
     let base = node_markup_attrs(node);
     let mut out = String::new();
     if !base.is_empty() {
         out.push_str("<span ");
         out.push_str(&base);
         out.push('>');
     }
     for segment in attributed.segments() {
         let text = &attributed.text()[segment.start as usize..segment.end as usize];
         let body = escape_pango(text);
         let attrs = run_markup_attrs(&segment.attributes);
         let body = if attrs.is_empty() {
             body
         } else {
             format!("<span {attrs}>{body}</span>")
         };
         let body = match segment.link {
             Some(url) => format!("<a href=\"{}\">{body}</a>", escape_pango_attr(url)),
             None => body,
         };
         out.push_str(&body);
     }
     if !base.is_empty() {
         out.push_str("</span>");
     }
     Some(out)
 }

 /// The node-level text-format properties as Pango markup attributes.
 fn node_markup_attrs(node: &HostNode) -> String {
     let mut parts = Vec::new();
     if let Some(v) = node.properties.get(&property_id::FONT_SIZE) {
         let size = f32::from_bits(*v);
         if size > 0.0 {
             parts.push(format!("size=\"{size}pt\""));
         }
     }
     if let Some(v) = node.properties.get(&property_id::FONT_WEIGHT) {
         let weight = f32::from_bits(*v);
         if weight > 0.0 {
             parts.push(format!("weight=\"{weight}\""));
         }
     }
     if let Some(v) = node.properties.get(&property_id::FONT_STYLE) {
         if f32::from_bits(*v) as u8 == 1 {
             parts.push("style=\"italic\"".to_string());
         }
     }
     if let Some(family) = node.string_property(property_id::FONT_FAMILY) {
         parts.push(format!("font_family=\"{}\"", escape_pango_attr(family)));
     } else if let Some(v) = node.properties.get(&property_id::FONT_DESIGN) {
         if let Some(family) = font_design_family(f32::from_bits(*v) as u8) {
             parts.push(format!("font_family=\"{family}\""));
         }
     }
     if let Some(v) = node.properties.get(&property_id::COLOR) {
         let c = *v;
         parts.push(format!(
             "foreground=\"#{:02x}{:02x}{:02x}\"",
             (c >> 16) & 0xFF,
             (c >> 8) & 0xFF,
             c & 0xFF
         ));
     }
     if node.u32_property(property_id::UNDERLINE, 0) != 0 {
         parts.push("underline=\"single\"".to_string());
     }
     if node.u32_property(property_id::STRIKETHROUGH, 0) != 0 {
         parts.push("strikethrough=\"true\"".to_string());
     }
     parts.join(" ")
 }

 /// The v1 run attributes as Pango markup attributes.
 fn run_markup_attrs(attributes: &[pathland_core::TextAttribute]) -> String {
     let mut parts = Vec::new();
     for attr in attributes {
         match attr.property {
             property_id::FONT_SIZE => {
                 let size = f32::from_bits(attr.value);
                 if size > 0.0 {
                     parts.push(format!("size=\"{size}pt\""));
                 }
             }
             property_id::FONT_WEIGHT => {
                 let weight = f32::from_bits(attr.value);
                 if weight > 0.0 {
                     parts.push(format!("weight=\"{weight}\""));
                 }
             }
             property_id::FONT_STYLE => {
                 if f32::from_bits(attr.value) as u8 == 1 {
                     parts.push("style=\"italic\"".to_string());
                 }
             }
             property_id::FONT_DESIGN => {
                 if let Some(family) = font_design_family(f32::from_bits(attr.value) as u8) {
                     parts.push(format!("font_family=\"{family}\""));
                 }
             }
             property_id::COLOR => {
                 let c = attr.value;
                 parts.push(format!(
                     "foreground=\"#{:02x}{:02x}{:02x}\"",
                     (c >> 16) & 0xFF,
                     (c >> 8) & 0xFF,
                     c & 0xFF
                 ));
             }
             property_id::UNDERLINE => {
                 if attr.value != 0 {
                     parts.push("underline=\"single\"".to_string());
                 }
             }
             property_id::STRIKETHROUGH => {
                 if attr.value != 0 {
                     parts.push("strikethrough=\"true\"".to_string());
                 }
             }
             _ => {}
         }
     }
     parts.join(" ")
 }

 fn escape_pango(text: &str) -> String {
     text.replace('&', "&amp;")
         .replace('<', "&lt;")
         .replace('>', "&gt;")
 }

 fn escape_pango_attr(value: &str) -> String {
     escape_pango(value).replace('"', "&quot;")
 }

 /// Run the GTK renderer over a shared ring, pumping frames in and waking the
 /// host on raw-input events.
 ///
 /// `on_event` is invoked (on the GTK main thread) with the shared ring whenever
 /// the renderer wrote a raw input; the app drains the ring's event queue itself
 /// (`RingTransport::drain_events`) and may re-emit a new frame.
 ///
 /// Passes the process's real program args to GTK (a native Rust binary's args
 /// are just its program name — safe for GTK to parse).
 pub fn run<F>(app_id: &str, title: &str, ring: Rc<RefCell<RingTransport>>, on_event: F)
 where
     F: FnMut(Rc<RefCell<RingTransport>>) + 'static,
 {
     let args: Vec<String> = std::env::args().collect();
     let args: Vec<&str> = args.iter().map(|s| s.as_str()).collect();
     run_with_pump(app_id, title, ring, &args, on_event);
 }

 /// Generic [`run`] over any [`Pump`] (e.g. a `pathland-view-native` host handle).
 ///
 /// `args` is passed verbatim to `g_application_run`. Embedding hosts must pass
 /// an argv that is NOT their own process command line when that command line
 /// carries foreign options (e.g. the JVM's `-cp`/`-D` flags).
 pub fn run_with_pump<P, F>(
     app_id: &str,
     title: &str,
     pump: Rc<RefCell<P>>,
     args: &[&str],
     on_event: F,
 ) where
     P: Pump + 'static,
     F: FnMut(Rc<RefCell<P>>) + 'static,
 {
     run_with_pump_sized(app_id, title, pump, args, on_event, 420, 220);
 }

 /// [`run_with_pump`] with an explicit default window size (embedding hosts that
 /// know the UI needs more room, e.g. a master-detail layout, pass their own).
 pub fn run_with_pump_sized<P, F>(
     app_id: &str,
     title: &str,
     pump: Rc<RefCell<P>>,
     args: &[&str],
     on_event: F,
     default_width: i32,
     default_height: i32,
 ) where
     P: Pump + 'static,
     F: FnMut(Rc<RefCell<P>>) + 'static,
 {
     let app_id = app_id.to_string();
     let title = title.to_string();
     let on_event = Rc::new(RefCell::new(on_event));

     let app = gtk::Application::builder().application_id(&app_id).build();

     app.connect_activate(move |app| {
         let fallback_title = title.clone();
         let window = gtk::ApplicationWindow::builder()
             .application(app)
             .title(&title)
             .default_width(default_width)
             .default_height(default_height)
             .build();

         let renderer = Rc::new(RefCell::new(GtkRenderer::new()));

         // Color-scheme detection (spec/TOKENS.md): the renderer derives the
         // effective scheme from the native GTK variant and re-resolves design
         // tokens when it changes. Scheme is NEVER carried by the protocol.
         if let Some(settings) = gtk::Settings::default() {
             let renderer_for_scheme = renderer.clone();
             settings.connect_gtk_application_prefer_dark_theme_notify(move |settings| {
                 renderer_for_scheme
                     .borrow_mut()
                     .set_scheme(tokens::scheme_from_settings(settings));
             });
             renderer
                 .borrow_mut()
                 .set_scheme(tokens::scheme_from_settings(&settings));
         }

         // Native inputs are written as EVENT opcodes into the pump (host → guest);
         // the host is then woken to drain the event ring itself.
         //
         // `emit` is the shared path for every raw input the renderer reports —
         // pointer/control events from the sink below, and platform back /
         // Escape-key navigation from the window-level key controller.
         //
         // A frame apply borrows the pump zero-copy (the batch aliases the shared
         // ring). Applying a value-bearing control's *programmatic* value
         // (e.g. `GtkScale::set_value`) fires its connected GTK signal
         // synchronously, re-entering `emit` while the pump is borrowed. Such
         // events are deferred to the idle pump (flushed before the next frame),
         // which also avoids a control echo loop when the host writes the same
         // value back.
         let pending: Rc<RefCell<Vec<Event>>> = Rc::new(RefCell::new(Vec::new()));
         let emit = {
             let pump = pump.clone();
             let wake = on_event.clone();
             let pending = pending.clone();
             move |ev: Event| match pump.try_borrow_mut() {
                 Ok(mut p) => {
                     let _ = p.send_input(&ev);
                     drop(p);
                     wake.borrow_mut()(pump.clone());
                 }
                 Err(_) => {
                     pending.borrow_mut().push(ev);
                 }
             }
         };
         {
             let emit_for_sink = emit.clone();
             let sink: Rc<RefCell<dyn FnMut(Event)>> =
                 Rc::new(RefCell::new(move |ev: Event| emit_for_sink(ev)));
             renderer.borrow_mut().set_event_sink(sink);

             // Platform back: Escape (and BackSpace when no text entry has focus)
             // is a native back request → `Event::Navigate { url: None }`. NAVIGATE
             // is global (never node-keyed), so it is attached once at the window
             // level, in the capture phase so it fires even when a child widget
             // holds focus. BackSpace is only mapped when the focused widget is
             // not a text input, so it never swallows text editing.
             let emit_for_key = emit.clone();
             let window_for_key = window.clone();
             let key = EventControllerKey::new();
             key.set_propagation_phase(PropagationPhase::Capture);
             key.connect_key_pressed(move |_key, keyval, _code, _state| {
                 let keyval = keyval.into_glib();
                 let is_escape = keyval == gtk::gdk::ffi::GDK_KEY_Escape as u32;
                 let is_backspace = keyval == gtk::gdk::ffi::GDK_KEY_BackSpace as u32
                     && !window_has_text_focus(&window_for_key);
                 if is_escape || is_backspace {
                     emit_for_key(Event::Navigate { url: None });
                     glib::Propagation::Stop
                 } else {
                     glib::Propagation::Proceed
                 }
             });
             window.add_controller(key);
         }

         // Initial render + window root. Deferred control signals from the mount
         // apply are flushed before the idle pump takes over.
         pump_once(&renderer, &pump);
         sync_window_metadata(&renderer, &window, &fallback_title);
         flush_pending(&pump, &pending, &on_event);
         let root = renderer.borrow().root_widget();
         if let Some(root) = root {
             window.set_child(Some(&root));
         }
         window.present();

         // Idle pump: flush any deferred (re-entrant) events, then apply pending
         // frames to the renderer. Events are drained by the host (woken from the
         // sink above), not here.
         let idle_renderer = renderer.clone();
         let idle_pump = pump.clone();
         let idle_pending = pending.clone();
         let idle_wake = on_event.clone();
         let idle_window = window.clone();
         let idle_title = fallback_title.clone();
         glib::idle_add_local(move || {
             flush_pending(&idle_pump, &idle_pending, &idle_wake);
             pump_once(&idle_renderer, &idle_pump);
             sync_window_metadata(&idle_renderer, &idle_window, &idle_title);
             glib::ControlFlow::Continue
         });
     });

     // Run the GTK main loop with the caller-provided argv.
     app.run_with_args(args);
 }

 /// Apply the decoded window/surface metadata to the GTK window chrome: title
 /// (falling back to the run-time default when unset) and the accessible
 /// description. Locale has no GTK window affordance.
 fn sync_window_metadata(
     renderer: &Rc<RefCell<GtkRenderer>>,
     window: &gtk::ApplicationWindow,
     fallback_title: &str,
 ) {
     let (title, description) = {
         let renderer = renderer.borrow();
         let metadata = renderer.window_metadata();
         (metadata.title.clone(), metadata.description.clone())
     };
     window.set_title(Some(title.as_deref().unwrap_or(fallback_title)));
     if let Some(description) = description.as_deref() {
         window.update_property(&[gtk::accessible::Property::Description(description)]);
     }
 }

 /// Whether a text input currently holds keyboard focus, so backspace is not
 /// misread as a platform-back navigation while the user is editing text.
 fn window_has_text_focus(window: &impl IsA<gtk::Window>) -> bool {
     let focused: Option<gtk::Widget> = window
         .upcast_ref::<gtk::Window>()
         .property::<Option<gtk::Widget>>("focus-widget");
     focused.map_or(false, |w| w.is::<gtk::Entry>() || w.is::<gtk::TextView>())
 }

 /// Flush events deferred during a frame apply (re-entrant control signals) into
 /// the pump and wake the host. Runs between frames, so the pump is free.
 fn flush_pending<P, F>(
     pump: &Rc<RefCell<P>>,
     pending: &Rc<RefCell<Vec<Event>>>,
     wake: &Rc<RefCell<F>>,
 ) where
     P: Pump,
     F: FnMut(Rc<RefCell<P>>),
 {
     if pending.borrow().is_empty() {
         return;
     }
     let events = std::mem::take(&mut *pending.borrow_mut());
     let mut p = pump.borrow_mut();
     for ev in events {
         let _ = p.send_input(&ev);
     }
     drop(p);
     wake.borrow_mut()(pump.clone());
 }

 /// Apply pending frames to the renderer. (Events flow the other way: the
 /// renderer writes them; the host drains them — see [`Pump`].)
 fn pump_once<P>(renderer: &Rc<RefCell<GtkRenderer>>, pump: &Rc<RefCell<P>>)
 where
     P: Pump,
 {
     loop {
         let mut pump_ref = pump.borrow_mut();
         match pump_ref.next_frame() {
             Ok(Some(batch)) => {
                 let frame = batch.frame();
                 renderer.borrow_mut().apply_frame(frame);
             }
             _ => break,
         }
     }
 }

 #[cfg(test)]
 mod tests {
     use super::*;
     use pathland_engine::Engine;
     use pathland_core::tokens::Scheme;
     use pathland_core::{init_memory, property_id, size, value_type, Guest, Host, MemoryLayout};
     use pathland_view::{assign_ids, text, vstack, Configurable, ForegroundStyle, View, ViewExt};

     #[test]
     fn size_hint_maps_width_height_sentinels() {
         assert_eq!(layout::size_hint(None), layout::SizeHint::None);
         assert_eq!(
             layout::size_hint(Some(size::FILL.to_bits())),
             layout::SizeHint::Fill
         );
         assert_eq!(
             layout::size_hint(Some(24.0f32.to_bits())),
             layout::SizeHint::Fixed(24)
         );
         // HUG_CONTENT (-2.0), zero, and non-finite values are natural size.
         assert_eq!(
             layout::size_hint(Some(size::HUG_CONTENT.to_bits())),
             layout::SizeHint::None
         );
         assert_eq!(layout::size_hint(Some(0.0f32.to_bits())), layout::SizeHint::None);
         assert_eq!(
             layout::size_hint(Some(f32::INFINITY.to_bits())),
             layout::SizeHint::None
         );
     }

     #[test]
     fn fit_rect_matches_object_fit_semantics() {
         // A 600x600 source in a 36x36 box → fills the box exactly.
         assert_eq!(fit_rect(600, 600, 36, 36, 0), (0, 0, 36, 36));
         // A 600x400 (3:2) source in a 36x36 box → fits by width, centered y.
         assert_eq!(fit_rect(600, 400, 36, 36, 0), (0, 6, 36, 24));
         // Fit scales up small sources too.
         assert_eq!(fit_rect(20, 10, 36, 36, 0), (0, 9, 36, 18));
         // Fill (cover): scale to cover the box; the scaled content extends past it
         // (negative centering offsets; the crop window is derived from w/h).
         assert_eq!(fit_rect(600, 400, 36, 36, 1), (-9, 0, 54, 36));
         assert_eq!(fit_rect(400, 600, 36, 36, 1), (0, -9, 36, 54));
     }

     #[test]
     fn scale_image_to_box_produces_a_points_sized_pixbuf() {
         use gdk_pixbuf::{Colorspace, Pixbuf};
         // A real 600x400 source, saved as PNG, then scaled into a 36x36 box:
         // both Fit and Fill must yield a 36x36 pixbuf (GtkPicture's natural size
         // then equals the requested points box).
         let src = Pixbuf::new(Colorspace::Rgb, false, 8, 600, 400).unwrap();
         src.fill(0x00FF0000); // red
         let path = std::env::temp_dir().join("pathland-scale-test.png");
         src.savev(&path, "png", &[]).unwrap();
         let fit = scale_image_to_box(path.to_str().unwrap(), 36, 36, 0).unwrap();
         assert_eq!((fit.width(), fit.height()), (36, 36));
         let cover = scale_image_to_box(path.to_str().unwrap(), 36, 36, 1).unwrap();
         assert_eq!((cover.width(), cover.height()), (36, 36));
         std::fs::remove_file(&path).ok();
     }

     #[test]
     fn render_tree_decodes_a_frame() {
         // Build a tree, emit into a ring, decode via RenderTree (the renderer's
         // underlying store) without touching GTK.
         let layout = MemoryLayout::default();
         let mut mem = vec![0u8; layout.total_bytes()];
         init_memory(&mut mem, &layout);

         let mut root = vstack![text("ab"), text("cd")]
             .with(|v| {
                 v.spacing(4.0);
             })
             .build();
         assign_ids(&mut root, &mut 1);

         let mut engine = Engine::new();
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             engine.emit(&root, &mut guest).unwrap();
             guest.end_frame();
         }

         let mut host = pathland_core::Host::new(&mut mem, &layout);
         let frames = host.frames();
         let mut tree = RenderTree::default();
         tree.apply_frame(&frames[0]);
         assert_eq!(tree.nodes.len(), 3);
         assert_eq!(tree.node(1).unwrap().component_type, component_type::VSTACK);
     }

     #[test]
     fn design_token_property_ref_resolves_against_concrete_defaults() {
         let layout = MemoryLayout::default();
         let mut mem = vec![0u8; layout.total_bytes()];
         init_memory(&mut mem, &layout);

         let mut root = text("x")
             .modifiers(ForegroundStyle(pathland_view::Color::token("color.primary")))
             .build();
         assign_ids(&mut root, &mut 1);

         let mut engine = Engine::new();
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             engine.emit(&root, &mut guest).unwrap();
             guest.end_frame();
         }

         let mut host = Host::new(&mut mem, &layout);
         let mut tree = RenderTree::default();
         tree.apply_frame(&host.frames()[0]);
         assert_eq!(
             tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(),
             Some(0xFF_2563EB),
             "color.primary concrete light default"
         );
     }

     #[test]
     fn design_token_override_and_scheme_change_re_resolve() {
         let layout = MemoryLayout::default();
         let mut mem = vec![0u8; layout.total_bytes()];
         init_memory(&mut mem, &layout);

         let mut root = text("x")
             .modifiers(ForegroundStyle(pathland_view::Color::token("color.primary")))
             .build();
         assign_ids(&mut root, &mut 1);
         let mut engine = Engine::new();
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             engine.emit(&root, &mut guest).unwrap();
             guest.end_frame();
         }
         let mut host = Host::new(&mut mem, &layout);
         let mut tree = RenderTree::default();
         tree.apply_frame(&host.frames()[0]);

         // Base override wins (light).
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             guest
                 .set_design_token("color.primary", value_type::COLOR, 0xFF_123456)
                 .unwrap();
             guest.end_frame();
             let mut host = Host::new(&mut mem, &layout);
             tree.apply_frame(&host.frames()[0]);
         }
         assert_eq!(
             tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(),
             Some(0xFF_123456),
             "base override wins (light)"
         );

         // Dark scheme: the base override falls through when the dark layer is empty.
         tree.set_scheme(Scheme::Dark);
         assert_eq!(
             tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(),
             Some(0xFF_123456),
             "base override falls through when the dark layer is empty"
         );

         // A dark.* override wins under the dark scheme.
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             guest
                 .set_design_token("dark.color.primary", value_type::COLOR, 0xFF_ABCDEF)
                 .unwrap();
             guest.end_frame();
             let mut host = Host::new(&mut mem, &layout);
             tree.apply_frame(&host.frames()[0]);
         }
         assert_eq!(
             tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(),
             Some(0xFF_ABCDEF),
             "dark.* override wins under dark"
         );

         // Back to light: the base override wins again.
         tree.set_scheme(Scheme::Light);
         assert_eq!(
             tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(),
             Some(0xFF_123456),
             "base override wins again under light"
         );
     }

     #[test]
     fn meta_scheme_override_and_theme_reset_re_resolve() {
         let layout = MemoryLayout::default();
         let mut mem = vec![0u8; layout.total_bytes()];
         init_memory(&mut mem, &layout);

         let mut root = text("x")
             .modifiers(ForegroundStyle(pathland_view::Color::token("color.primary")))
             .build();
         assign_ids(&mut root, &mut 1);
         let mut engine = Engine::new();
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             engine.emit(&root, &mut guest).unwrap();
             guest.end_frame();
         }
         let mut host = Host::new(&mut mem, &layout);
         let mut tree = RenderTree::default();
         tree.apply_frame(&host.frames()[0]);
         assert_eq!(
             tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(),
             Some(0xFF_2563EB)
         );

         // META::SET_COLOR_SCHEME(DARK) forces the dark layer.
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             guest
                 .set_color_scheme(pathland_core::color_scheme_mode::DARK)
                 .unwrap();
             guest.end_frame();
             let mut host = Host::new(&mut mem, &layout);
             tree.apply_frame(&host.frames()[0]);
         }
         assert_eq!(tree.scheme(), Scheme::Dark);
         assert_eq!(
             tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(),
             Some(0xFF_60A5FA)
         );

         // A base override + RESET_THEME returns to the forced-dark default.
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             guest
                 .set_design_token("color.primary", value_type::COLOR, 0xFF_112233)
                 .unwrap();
             guest.end_frame();
             let mut host = Host::new(&mut mem, &layout);
             tree.apply_frame(&host.frames()[0]);
         }
         assert_eq!(
             tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(),
             Some(0xFF_112233)
         );
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             guest.reset_theme().unwrap();
             guest.end_frame();
