 /// The bidirectional transport surface the renderer pumps: frames in
 /// (guest → host) and events out (host → guest).
 pub trait Pump {
     /// Read the next guest → host frame.
     fn next_frame(&mut self) -> Result<Option<OpcodeBatch<'_>>, TransportError>;
     /// Write a host → guest raw input as an `EVENT` opcode.
     fn send_input(&mut self, event: &Event) -> Result<(), TransportError>;
 }

 impl Pump for RingTransport {
     fn next_frame(&mut self) -> Result<Option<OpcodeBatch<'_>>, TransportError> {
         FrameSource::next_frame(self)
     }
     fn send_input(&mut self, event: &Event) -> Result<(), TransportError> {
         DriverTransport::send_input(self, event)
     }
 }

 /// A host-supplied event callback, invoked (with no payload) when the renderer
 /// has written a raw input into the host → guest event ring. The host drains
 /// the ring itself.
 pub type EventCallback = extern "C" fn();

 /// What to do with a Qt raw input.
 enum QtAction {
     /// Encode + write into the event ring, then wake the host.
     Send(Event),
     /// A platform color-scheme change: re-resolve tokens in the renderer
     /// (no host wake — the re-apply flows back as `SET_PROPERTY` commands).
     Scheme(Scheme),
     None,
 }

 /// Decode a `QtEvent` (C++ → Rust) into an action.
 fn decode_event(raw: &QtEvent) -> QtAction {
     match raw.kind {
         ev::POINTER_DOWN => QtAction::Send(Event::PointerDown {
             target: raw.node_id,
             x: raw.x,
             y: raw.y,
             secondary: false,
         }),
         ev::POINTER_MOVE => QtAction::Send(Event::PointerMove {
             target: raw.node_id,
             x: raw.x,
             y: raw.y,
             hovering: false,
             leaving: false,
         }),
         ev::POINTER_UP => QtAction::Send(Event::PointerUp {
             target: raw.node_id,
             x: raw.x,
             y: raw.y,
             secondary: false,
         }),
         ev::VALUE_CHANGED => QtAction::Send(Event::ValueChanged {
             target: raw.node_id,
             value: raw.value,
         }),
         ev::TEXT_CHANGED => {
             // The string is length-prefixed, not guaranteed NUL-terminated.
             let slice =
                 unsafe { std::slice::from_raw_parts(raw.str_ as *const u8, raw.str_len as usize) };
             QtAction::Send(Event::TextChanged {
                 target: raw.node_id,
                 value: String::from_utf8_lossy(slice).into_owned(),
             })
         }
         ev::NAVIGATE_BACK => QtAction::Send(Event::Navigate { url: None }),
         // Media transport reports target the MEDIA_CONTROLLER (spec/MEDIA.md).
         ev::MEDIA_PLAY_STATE => QtAction::Send(Event::MediaPlayStateChanged {
             target: raw.node_id,
             playing: raw.value >= 0.5,
         }),
         ev::MEDIA_TIME => QtAction::Send(Event::MediaTimeUpdated {
             target: raw.node_id,
             seconds: raw.value,
         }),
         ev::MEDIA_ENDED => QtAction::Send(Event::MediaEnded {
             target: raw.node_id,
         }),
         ev::MEDIA_VOLUME => QtAction::Send(Event::MediaVolumeChanged {
             target: raw.node_id,
             volume: raw.value,
         }),
         ev::MEDIA_DURATION => QtAction::Send(Event::MediaDurationChanged {
             target: raw.node_id,
             seconds: raw.value,
         }),
         ev::FIT_CHANGED => QtAction::Send(Event::FitChanged {
             target: raw.node_id,
             index: raw.value,
         }),
+        ev::VISIBLE_RANGE => QtAction::Send(Event::VisibleRange {
+            target: raw.node_id,
+            first_index: raw.first_index,
+            count: raw.count,
+        }),
         ev::POINTER_ENTER => QtAction::Send(Event::PointerMove {
             target: raw.node_id,
             x: 0.0,
             y: 0.0,
             hovering: true,
             leaving: false,
         }),
         ev::POINTER_LEAVE => QtAction::Send(Event::PointerMove {
             target: raw.node_id,
             x: 0.0,
             y: 0.0,
             hovering: false,
             leaving: true,
         }),
         ev::KEY_DOWN => QtAction::Send(Event::KeyDown {
             target: raw.node_id,
             key_code: raw.key_code,
             modifiers: raw.modifiers,
             repeat: raw.repeat != 0,
         }),
         ev::KEY_UP => QtAction::Send(Event::KeyUp {
             target: raw.node_id,
             key_code: raw.key_code,
             modifiers: raw.modifiers,
         }),
         ev::FOCUS => QtAction::Send(Event::FocusChanged {
             target: raw.node_id,
             focused: raw.value >= 0.5,
         }),
         ev::EDITING => QtAction::Send(Event::EditingChanged {
             target: raw.node_id,
             editing: raw.value >= 0.5,
         }),
         ev::SUBMIT => QtAction::Send(Event::Submit {
