Good. Now add the helper functions `refreshLazyStacks`, `refreshLazyStack`, `reportLazyRange`, and the scroll ancestor finder. Where to place? After `layoutOf`/`layoutAttached` helpers (around line 960) or before `pathland_qt_layer_apply`. The functions need `g`, `findWidget`, `layoutOf`, `layoutAttached`, `QQuickScrollView`? We can use `inherits("QQuickScrollView")`. They also need `g.bridge`. Let me place them after `layoutAttached` (line ~965) so they can be used by `pathland_qt_layer_apply` (defined later) and `deleteNode`/`reset`. The `deleteNode` function is defined later; it can call a cleanup helper. We'll add cleanup inline.

Implementation:
```cpp
QQuickItem *scrollAncestor(QQuickItem *item) {
    for (QQuickItem *p = item ? item->parentItem() : nullptr; p; p = p->parentItem()) {
        if (p->inherits("QQuickScrollView")) return p;
    }
    return nullptr;
}

QQuickItem *scrollContent(QQuickItem *sw) {
    if (!sw) return nullptr;
    return sw->property("contentItem").value<QQuickItem *>();
}

void reportLazyRange(uint32_t id) {
    QQuickItem *item = findWidget(id);
    if (!item) return;
    auto ci = g.lazy_count.find(id);
    auto ei = g.lazy_extent.find(id);
    if (ci == g.lazy_count.end() || ei == g.lazy_extent.end()) return;
    const uint32_t count = ci->second;
    const double extent = ei->second;
    if (count == 0 || extent <= 0.0) return;
    const double spacing = g.lazy_spacing.count(id) ? g.lazy_spacing[id] : 0.0;
    const double stride = extent + std::max(0.0, spacing);
    QQuickItem *sw = scrollAncestor(item);
    QQuickItem *content = scrollContent(sw);
    if (!sw || !content) return;
    const bool vertical = g.components[id] == PL_COMP_LAZY_VSTACK;
    const QPointF origin = item->mapToItem(content, QPointF(0, 0));
    const double offset = vertical ? origin.y() : origin.x();
    const double viewStart = vertical ? content->property("contentY").toDouble()
                                      : content->property("contentX").toDouble();
    const double viewport = vertical ? sw->height() : sw->width();
    const double start = viewStart - offset;
    const double end = start + viewport;
    const uint32_t first = std::min(count, static_cast<uint32_t>(std::max(0.0, std::floor(start / stride))));
    const uint32_t last = std::min(count, static_cast<uint32_t>(std::max(0.0, std::ceil(end / stride))));
    const uint32_t visible = last > first ? last - first : 0;
    auto &previous = g.lazy_last[id];
    if (previous.first == first && previous.second == visible) return;
    previous = {first, visible};
    if (g.bridge) g.bridge->visibleRange(id, first, visible);
}

void refreshLazyStack(uint32_t id) {
    QQuickItem *item = findWidget(id);
    if (!item) return;
    auto ci = g.lazy_count.find(id);
    auto ei = g.lazy_extent.find(id);
    if (ci == g.lazy_count.end() || ei == g.lazy_extent.end()) return;
    const uint32_t count = ci->second;
    const double extent = ei->second;
    if (count == 0 || extent <= 0.0) return;
    QQuickItem *lay = layoutOf(item);
    if (!lay) return;
    const bool vertical = g.components[id] == PL_COMP_LAZY_VSTACK;
    const double spacing = g.lazy_spacing.count(id) ? g.lazy_spacing[id] : 0.0;
    const uint32_t first = g.lazy_first.count(id) ? g.lazy_first[id] : 0;
    const size_t childCount = g.children_of.count(id) ? g.children_of[id].size() : 0;
    const double stride = extent + std::max(0.0, spacing);
    const double leading = std::max(0.0, first * stride - std::max(0.0, spacing));
    const double trailing = std::max(0.0, (count > first + childCount ? count - first - childCount : 0) * stride - std::max(0.0, spacing));

    // Remove old spacers.
    auto sit = g.lazy_spacers.find(id);
    if (sit != g.lazy_spacers.end()) {
        for (QQuickItem *w : sit->second) {
            w->setParentItem(nullptr);
            w->deleteLater();
        }
        sit->second.clear();
    }
    auto addSpacer = [&](double size, bool leadingSpacer) {
        if (size <= 0.0) return;
        auto *spacer = new QQuickItem();
        spacer->setParentItem(lay);
        if (QQuickLayoutAttached *a = layoutAttached(spacer)) {
            if (vertical) {
                a->setPreferredHeight(size);
                a->setFillWidth(true);
            } else {
                a->setPreferredWidth(size);
                a->setFillHeight(true);
            }
        }
        if (leadingSpacer) {
            const auto kids = lay->childItems();
            if (kids.size() > 1) spacer->stackBefore(kids.first());
        }
        g.lazy_spacers[id].push_back(spacer);
    };
    addSpacer(leading, true);
    addSpacer(trailing, false);

    // Attach the scroll observer once (the scroll ancestor may appear later).
    if (g.lazy_attached.count(id)) {
        reportLazyRange(id);
        return;
    }
    QQuickItem *sw = scrollAncestor(item);
    QQuickItem *content = scrollContent(sw);
    if (!sw || !content) return;
    QObject::connect(content, SIGNAL(contentYChanged()), item, [id]() { reportLazyRange(id); });
    QObject::connect(content, SIGNAL(contentXChanged()), item, [id]() { reportLazyRange(id); });
    QObject::connect(sw, &QQuickItem::widthChanged, item, [id]() { reportLazyRange(id); });
    QObject::connect(sw, &QQuickItem::heightChanged, item, [id]() { reportLazyRange(id); });
    g.lazy_attached.insert(id);
    reportLazyRange(id);
}

void refreshLazyStacks() {
    std::vector<uint32_t> ids;
    ids.reserve(g.lazy_count.size());
    for (const auto &kv : g.lazy_count) ids.push_back(kv.first);
    for (uint32_t id : ids) refreshLazyStack(id);
}
